import { describe, expect, it } from "vitest";
import fixtures from "./fixtures/parity.json" with { type: "json" };
import { checkCv } from "../src/check.js";
import { getSampleCvText } from "../src/samples.js";
import type { CvCheckInput } from "../src/types.js";

// tests/fixtures/parity.json holds the output of the hosted app's engine,
// generated by scripts/generate-fixtures.ts at the commit recorded in the file.
// This test only reads that file, so it needs no access to the app repo.

describe("parity with the hosted engine", () => {
  it("records which commit the fixtures came from", () => {
    expect(fixtures.generatedFrom.sha).toMatch(/^[0-9a-f]{40}$/);
  });

  it("covers the EN, SV and FR samples, a JD case and a sub-40-word case", () => {
    const names = fixtures.cases.map((c) => c.name);
    expect(names).toEqual(
      expect.arrayContaining([
        "sample-en",
        "sample-sv",
        "sample-fr",
        "sample-en-with-jd",
        "under-40-words",
      ]),
    );
  });

  it.each(fixtures.cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const result = checkCv(c.input as CvCheckInput);
    expect(result.score).toBe(c.expected.score);
    expect(result.categories).toEqual(c.expected.categories);
    expect(result.findings).toEqual(c.expected.findings);
    expect(result.matchedKeywords).toEqual(c.expected.matchedKeywords);
    expect(result.missingKeywords).toEqual(c.expected.missingKeywords);
    expect(result.wordCount).toBe(c.expected.wordCount);
    expect(result.estimatedPages).toBe(c.expected.estimatedPages);
  });

  it.each(["en", "sv", "fr"] as const)("bundled %s sample is byte-identical to the fixture input", (locale) => {
    const fixture = fixtures.cases.find((c) => c.name === `sample-${locale}`)!;
    expect(getSampleCvText(locale)).toBe(fixture.input.text);
  });
});
